595	/*--------------------------------------
596	 * safe-prime comparison: with v[] storing x * mod small-primes[],
597	 * report if any of the P|x or P|2x+1: r[] will be all-00 if no factor
598	 *
599	 * since comparing to 0 is expected intrinsic, report 0 if dividing, >0 if not
600	 * 'v' is x * 1/prime
601	 *
602	 * 'r' is filled with 16x16-bit result
603	 *     ffff  entry divides x  OR  divides 2x+1
604	 *        0  divides none
605	 *
606	 * (1) A1 =  x * 1/prime   mod 2^16
607	 * (2) A1 <= B             <->  prime divides x
608	 *
609	 * (3) A2 = (2x + 1) * 1/prime  mod 2^16  ==
610	 *          (2 * A1 + 1/prime)  mod 2^16
611	 * (4) A2 <= B             <->  prime divides 2x+1
612	 *
613	 *------------------------------------*/
614	static inline
615	REALLY_FORCE_INLINE
616	//
617	void simd_spcmp16x16(uint16_t r[static 16], const uint16_t v[static 16],
618	             const uint16_t inv[static 16],
619	           const uint16_t limit[static 16])
620	{
621		uint16_t tmp[16];
622	// TODO: use external tmp[] which may be centrally wiped
623	
624		simd_shladd16x16(tmp, v, inv);                   // 2*v+inv[]  mod 2^16
625	
626		simd_min16x16(r, v, tmp);
627	
628		simd_lemask16x16_inpl(r, limit);           // divides -> ffff; not -> 0
629	}
